from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    result = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, h))
                for j in range(c, min(c + 3, w))
                if grid[i][j] != 5
            )
            row.append(counts.most_common(1)[0][0] if counts else 5)
        result.append(row)
    return result
